import { Component, effect, inject, signal } from '@angular/core';

@Component({
  selector: 'app-product-search',
  templateUrl: './product-search.html',
})
export class ProductSearch {
  private readonly api = inject(ProductApi);
  readonly query = signal('');
  readonly results = signal<Product[]>([]);

  constructor() {
    // A request per keystroke, and a slow old response can win
    effect(() => {
      this.api.search(this.query()).subscribe((r) => this.results.set(r));
    });
  }
}

import { Component, inject, signal } from '@angular/core';
import { toObservable, toSignal } from '@angular/core/rxjs-interop';
import { debounceTime, switchMap } from 'rxjs';

@Component({
  selector: 'app-product-search',
  templateUrl: './product-search.html',
})
export class ProductSearch {
  private readonly api = inject(ProductApi);
  readonly query = signal('');

  // Events stay in RxJS; the template reads the latest result as a signal
  readonly results = toSignal(
    toObservable(this.query).pipe(
      debounceTime(300),
      switchMap((q) => this.api.search(q)), // cancels the stale request
    ),
    { initialValue: [] },
  );
}

